function prepareEmailSummaryWindow({ searchScope, recipient, cc }, anchor) {
  const cleanAddress = (value) => {
    if (typeof value !== 'string' || !/^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/u.test(value.trim())) throw new Error('Configure a plain recipient email address.');
    return value.trim();
  };
  if (typeof searchScope !== 'string' || !searchScope.trim() || searchScope.includes('YOUR_GMAIL_SEARCH_SCOPE')) throw new Error('Configure the Gmail search scope.');
  const to = cleanAddress(recipient);
  if (!Array.isArray(cc)) throw new Error('CC must be an array of plain email addresses.');
  const copies = cc.map(cleanAddress), end = new Date(anchor).getTime();
  if (!Number.isSafeInteger(end) || end < Date.UTC(2000, 0, 2)) throw new Error('Invalid captured execution time.');
  const offset = 330 * 60 * 1000, local = new Date(end + offset);
  const today = Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate());
  const start = today - 86400000 - offset, endSeconds = Math.floor(end / 1000);
  const startDate = new Date(start + offset).toISOString().slice(0, 10);
  const endLabel = local.toISOString().slice(0, 16).replace('T', ' ');
  return { query: '(' + searchScope.trim() + ') after:' + Math.floor(start / 1000) + ' before:' + endSeconds,
    recipient: to, cc: copies, windowStart: new Date(start).toISOString(), windowEnd: new Date(endSeconds * 1000).toISOString(),
    subject: 'Email summary | ' + startDate + ' 00:00 to ' + endLabel + ' Asia/Kolkata' };
}

function prepareWindow(input) {
  return prepareEmailSummaryWindow(input, new Date().toISOString());
}

return [{json:prepareEmailSummaryWindow(settings,$now.toISO()),pairedItem:{item:0}}];

function emailSummaryFields(message, id, alreadyDecoded = false) {
  if (typeof id !== 'string' || !id || !message || message.messageId !== id || (message.snippet != null && typeof message.snippet !== 'string')) throw new Error('Gmail returned a different message or invalid snippet.');
  const headers = message.payload?.headers ?? [];
  if (!Array.isArray(headers)) throw new Error('Gmail did not return message headers.');
  const header = (name) => {
    const values = headers.filter((entry) => typeof entry?.name === 'string' && entry.name.toLowerCase() === name);
    if (values.some((entry) => typeof entry.value !== 'string')) throw new Error('Gmail returned an invalid header.');
    return values.map((entry) => entry.value).join(', ');
  };
  const rawSnippet = message.snippet ?? '';
  const snippet = alreadyDecoded ? rawSnippet : rawSnippet.replace(/&amp;|&lt;|&gt;|&#39;|&quot;/gu, (entity) => ({ '&amp;': '&', '&lt;': '<', '&gt;': '>', '&#39;': "'", '&quot;': '"' })[entity]);
  return { id, From: header('from'), To: header('to'), CC: header('cc'), snippet };
}

async function readSummaryMessages({ messageIds }, context) {
  if (!Array.isArray(messageIds) || messageIds.some((id) => typeof id !== 'string' || !id)) throw new Error('Invalid Gmail message IDs.');
  const messages = [];
  for (const messageId of messageIds) {
    context.signal?.throwIfAborted();
    const message = await context.actions.call('gmail.fetch_message_by_message_id', { messageId, format: 'metadata' });
    messages.push(emailSummaryFields(message, messageId));
  }
  return { emailData: JSON.stringify(messages), count: messages.length };
}

